#include <LoRa.h>
void setup() {
    Serial.begin(115200);
    LoRa.setPins(5, 14, 26);
    LoRa.begin({{freq_hz}});
}
void loop() {
    int packetSize = LoRa.parsePacket();
    if (packetSize) {
        String s;
        while (LoRa.available()) s += (char)LoRa.read();
        Serial.printf("rx (%d dBm): %s\n", LoRa.packetRssi(), s.c_str());
    }
}
